insert into public.guides (name_ar,name_en,bio_ar,bio_en,city_ar,city_en,country_ar,country_en,languages,specialties,price,currency,avatar_url,verified,published,is_demo)
select d.* from demo_guides d
where not exists (
  select 1 from public.guides g
  where g.is_demo = true and g.name_en = d.name_en
);
